function processOrder(order) {
  validate(order);
  const fee = calculateFee(order);
  for (const item of order.items) {
    item.price = applyDiscount(item);
    updateInventory(item);
  }
  sendConfirmation(order);
  logAudit(order);
}

function calculateInvoice(items) {
  let subtotal = 0;
  for (const i of items) {
    subtotal += i.price * i.quantity - i.discount;
  }
  const tax = computeTax(subtotal);
  return subtotal + tax;
}

function processPayment(ctx: PaymentContext) {
  // Version A
  function chargeEverything() {
    const total = ctx.items.reduce((s, i) => s + i.amount, 0);
    ctx.gateway.charge(ctx.user, total);
    ctx.audit.log('charged', ctx.user.id);
  }

  // Version B
  function calculateTotal(items) {
    return items.reduce((s, i) => s + i.amount, 0);
  }
  const total = calculateTotal(ctx.items);
  ctx.gateway.charge(ctx.user, total);
  ctx.audit.log('charged', ctx.user.id);
}
